fn parse_port(text: &str) -> Result<u16, PortError> {
    let port: u16 = text.parse().map_err(|_| PortError::NotANumber)?;
    if port == 0 { return Err(PortError::OutOfRange); }
    Ok(port)
}

let port = parse_port(raw).unwrap_or(8080);

match parse_port(raw) {
    Ok(port) => bind(port),
    Err(e) => eprintln!("invalid port: {e}"),
}

